{"chunk_id":"008b70","wall_time_seconds":0.455777,"exit_code":1,"original_token_count":5884,"output":"/****************************************************************************
 * Contest 2026 team 236 - Anime Voice Companion
 *
 * anime_voice_main.c - application entry point.
 *
 * Brings up LVGL on the Gemini-S1 panel (/dev/lcd0), then wires the UI, the
 * Wi-Fi helper and the push-to-talk voice loop together:
 *
 *      +--------+   PTT down    +-----------+   ASR text   +-----------+
 *      |  idle  |-------------->| listening |------------->| thinking  |
 *      +--------+               +-----------+              +-----------+
 *            ^                                                |
 *            |            TTS finished                        | LLM reply
 *            |                                                v
 *            |   +------------------------------------+  +-----------+
 *            +---|              speaking              |<-|  reply    |
 *                +------------------------------------+  +-----------+
 *
 * Everything that blocks on the network (ASR / LLM / TTS) runs on the
 * ai_agent worker threads.  Their callbacks only stash a result into a small
 * mutex protected slot; the LVGL timer at 30 ms drains it and is therefore
 * the only place that touches widget state.
 *
 * When the Vela AI Agent is not reachable the app still works as a demo:
 * a tap on the character returns a line from the built-in offline persona
 * table, and the status bar keeps showing the Wi-Fi state.
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <syslog.h>
#include <unistd.h>

#include <lvgl/lvgl.h>

#include "av_common.h"
#include "av_font.h"
#include "av_persona.h"
#include "av_ui.h"
#include "av_voice.h"
#include "av_wifi.h"

#ifdef CONFIG_LV_USE_NUTTX_LIBUV
#  include <uv.h>
#endif

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define AV_TAG              "anime_voice"

#define AV_TICK_MS          30

/* How long to wait for the microphone stream to come up after a PTT press
 * before giving up on the utterance. */

#define AV_START_TIMEOUT    (2000 / AV_TICK_MS)

/* Keep the "error" face on screen for a moment before going idle again. */

#define AV_ERROR_HOLD       (3000 / AV_TICK_MS)

/* Startup grace period: the agent may boot a second after us. */

#define AV_BOOT_PROBE       (1200 / AV_TICK_MS)

#define AV_EV_TEXT_MAX      512

/****************************************************************************
 * Private Types
 ****************************************************************************/

enum av_ev_e
{
  AV_EV_NONE = 0,
  AV_EV_STT,        /* ASR finished               */
  AV_EV_REPLY,      /* LLM answered               */
  AV_EV_SPOKEN      /* TTS playback finished      */
};

struct av_ev_s
{
  int  kind;
  char text[AV_EV_TEXT_MAX];
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct av_ev_s  g_ev;
static pthread_mutex_t g_ev_lock = PTHREAD_MUTEX_INITIALIZER;

static volatile int    g_req_stop;    /* PTT released, waiting for the mic   */
static int             g_stop_wait;
static volatile int    g_offline_press;

static int             g_error_hold;
static int             g_boot_wait;

static bool            g_force_offline;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: av_ev_post
 *
 * Description:
 *   Called from ai_agent worker threads.  Only touches the event slot, never
 *   LVGL.
 ****************************************************************************/

static void av_ev_post(int kind, const char *text)
{
  pthread_mutex_lock(&g_ev_lock);

  g_ev.kind = kind;
  if (text != NULL)
    {
      strncpy(g_ev.text, text, sizeof(g_ev.text) - 1);
      g_ev.text[sizeof(g_ev.text) - 1] = '\0';
    }
  else
    {
      g_ev.text[0] = '\0';
    }

  pthread_mutex_unlock(&g_ev_lock);
}

/****************************************************************************
 * Name: av_ev_take
 *
 * Description:
 *   Drain the slot.  Returns the event kind, copies the text out.
 ****************************************************************************/

static int av_ev_take(char *out, size_t cap)
{
  int kind;

  out[0] = '\0';

  pthread_mutex_lock(&g_ev_lock);

  kind = g_ev.kind;
  if (kind != AV_EV_NONE)
    {
      strncpy(out, g_ev.text, cap - 1);
      out[cap - 1] = '\0';
      g_ev.kind    = AV_EV_NONE;
      g_ev.text[0] = '\0';
    }

  pthread_mutex_unlock(&g_ev_lock);

  return kind;
}

/****************************************************************************
 * ai_agent worker callbacks
 ****************************************************************************/

static void av_on_stt(const char *text, void *cookie)
{
  (void)cookie;
  av_ev_post(AV_EV_STT, text);
}

static void av_on_reply(const char *text, void *cookie)
{
  (void)cookie;
  av_ev_post(AV_EV_REPLY, text);
}

static void av_on_spoken(const char *text, void *cookie)
{
  (void)cookie;
  av_ev_post(AV_EV_SPOKEN, text);
}

/****************************************************************************
 * UI callbacks (LVGL thread)
 ****************************************************************************/

/****************************************************************************
 * Name: av_on_ptt_down
 ****************************************************************************/

static void av_on_ptt_down(void)
{
  if (g_force_offline || !av_voice_agent_ready())
    {
      /* No ASR available: degrade the button to a "poke" gesture so the
       * demo stays interactive. */

      g_offline_press = 1;
      av_ui_set_state(AV_STATE_IDLE);
      av_ui_push(AV_ROLE_SYS, "语音服务未就绪，点角色可先聊两句");
      return;
    }

  g_offline_press = 0;
  g_req_stop      = 0;
  g_stop_wait     = 0;

  av_ui_set_state(AV_STATE_LISTENING);
  av_ui_set_mic_active(true);

  if (av_voice_start() < 0)
    {
      av_ui_set_mic_active(false);
      av_ui_set_state(AV_STATE_ERROR);
      av_ui_push(AV_ROLE_SYS, "麦克风打开失败");
    }
}

/****************************************************************************
 * Name: av_on_ptt_up
 ****************************************************************************/

static void av_on_ptt_up(void)
{
  av_ui_set_mic_active(false);

  if (g_offline_press)
    {
      g_offline_press = 0;
      av_ui_push(AV_ROLE_CHAR, av_persona_idle_line());
      return;
    }

  /* The microphone stream is opened asynchronously, so recording may not
   * have started yet.  Flag the request and let the timer close it once the
   * stream is live. */

  g_req_stop  = 1;
  g_stop_wait = 0;
  av_ui_set_status_text("识别中…");
}

/****************************************************************************
 * Name: av_on_idle_tap
 *
 * Description:
 *   A short tap on the character.  Turns into a one-shot small-talk request
 *   so the companion reacts even without the microphone.
 ****************************************************************************/

static void av_on_idle_tap(void)
{
  if (g_force_offline || av_ui_get_state() == AV_STATE_SPEAKING)
    {
      av_ui_push(AV_ROLE_CHAR, av_persona_idle_line());
      return;
    }

  if (!av_voice_agent_ready())
    {
      av_ui_push(AV_ROLE_CHAR, av_persona_idle_line());
      return;
    }

  av_ui_set_state(AV_STATE_THINKING);

  if (av_voice_ask("（用户戳了戳你）用一句话跟我打个招呼吧。") < 0)
    {
      av_ui_push(AV_ROLE_CHAR, av_persona_idle_line());
      av_ui_set_state(AV_STATE_IDLE);
    }
}

/****************************************************************************
 * Name: av_handle_event
 ****************************************************************************/

static void av_handle_event(int kind, const char *text)
{
  switch (kind)
    {
      case AV_EV_STT:
        if (text[0] == '\0')
          {
            av_ui_push(AV_ROLE_CHAR, av_persona_listen_line());
            av_ui_set_state(AV_STATE_IDLE);
            break;
          }

        av_ui_push(AV_ROLE_USER, text);

        if (av_voice_ask(text) < 0)
          {
            av_ui_push(AV_ROLE_CHAR, av_persona_nonet_line());
            av_ui_set_state(AV_STATE_ERROR);
            break;
          }

        av_ui_set_state(AV_STATE_THINKING);
        break;

      case AV_EV_REPLY:
        if (text[0] == '\0')
          {
            av_ui_push(AV_ROLE_CHAR, av_persona_nonet_line());
            av_ui_set_state(AV_STATE_ERROR);
            break;
          }

        av_ui_push(AV_ROLE_CHAR, text);
        av_ui_set_state(AV_STATE_SPEAKING);

        if (av_voice_speak(text) < 0)
          {
            av_ui_set_state(AV_STATE_IDLE);
          }
        break;

      case AV_EV_SPOKEN:
        av_ui_set_state(AV_STATE_IDLE);
        break;

      default:
        break;
    }
}

/****************************************************************************
 * Name: av_timer_cb
 *
 * Description:
 *   The only place that mutates widgets outside of the UI event callbacks.
 *   Runs on the LVGL thread every AV_TICK_MS.
 ****************************************************************************/

static void av_timer_cb(lv_timer_t *timer)
{
  char text[AV_EV_TEXT_MAX];
  int  kind;

  (void)timer;

  /* Startup probe: report whether the voice backend is reachable. */

  if (g_boot_wait >= 0)
    {
      if (++g_boot_wait >= AV_BOOT_PROBE)
        {
          g_boot_wait = -1;

          if (g_force_offline)
            {
              av_ui_push(AV_ROLE_SYS, "离线演示模式");
            }
          else if (av_voice_agent_ready())
            {
              av_ui_push(AV_ROLE_SYS, "语音服务已就绪，按住下方按钮开始对话");
            }
          else
            {
              av_ui_push(AV_ROLE_SYS,
                         "未检测到语音服务，点角色可离线闲聊");
            }

          av_ui_set_state(AV_STATE_IDLE);
        }
    }

  /* PTT release: close the stream once the microphone is actually open. */

  if (g_req_stop)
    {
      if (av_voice_is_recording())
        {
          g_req_stop  = 0;
          g_stop_wait = 0;
          av_ui_set_state(AV_STATE_THINKING);
          av_voice_stop();
        }
      else if (++g_stop_wait > AV_START_TIMEOUT)
        {
          g_req_stop  = 0;
          g_stop_wait = 0;
          av_ui_push(AV_ROLE_CHAR, av_persona_listen_line());
          av_ui_set_state(AV_STATE_IDLE);
        }
    }

  /* Drain worker results. */

  kind = av_ev_take(text, sizeof(text));
  if (kind != AV_EV_NONE)
    {
      av_handle_event(kind, text);
    }

  /* Auto clear the error face. */

  if (av_ui_get_state() == AV_STATE_ERROR)
    {
      if (++g_error_hold > AV_ERROR_HOLD)
        {
          g_error_hold = 0;
          av_ui_set_state(AV_STATE_IDLE);
        }
    }
  else
    {
      g_error_hold = 0;
    }

  /* Screen animations, star field, level bars, Wi-Fi polling. */

  av_ui_tick();
}

/****************************************************************************
 * Name: av_uv_loop / av_poll_loop
 ****************************************************************************/

#ifdef CONFIG_LV_USE_NUTTX_LIBUV
static void av_uv_loop(uv_loop_t *loop, lv_nuttx_result_t *result)
{
  lv_nuttx_uv_t uv_info;
  void         *data;

  uv_loop_init(loop);

  lv_memset(&uv_info, 0, sizeof(uv_info));
  uv_info.loop   = loop;
  uv_info.disp   = result->disp;
  uv_info.indev  = result->indev;
#ifdef CONFIG_UINPUT_TOUCH
  uv_info.uindev = result->utouch_indev;
#endif

  data = lv_nuttx_uv_init(&uv_info);
  uv_run(loop, UV_RUN_DEFAULT);
  lv_nuttx_uv_deinit(&data);
}
#else
static void av_poll_loop(void)
{
  while (1)
    {
      uint32_t idle = lv_timer_handler();

      usleep((idle ? idle : 1) * 1000);
    }
}
#endif

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t    info;
  lv_nuttx_result_t result;
#ifdef CONFIG_LV_USE_NUTTX_LIBUV
  uv_loop_t         ui_loop;
#endif
  av_ui_events_t    events;
  int               i;
  int               ret;

  for (i = 1; i < argc; i++)
    {
      if (strcmp(argv[i], "--offline") == 0 ||
          strcmp(argv[i], "offline") == 0)
        {
          g_force_offline = true;
        }
    }

  syslog(LOG_INFO, "%s: starting%s\n", AV_TAG,
         g_force_offline ? " (offline demo mode)" : "");

  if (lv_is_initialized())
    {
      syslog(LOG_ERR, "%s: LVGL already initialised\n", AV_TAG);
      return -EBUSY;
    }

  lv_init();

  lv_nuttx_dsc_init(&info);

#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif

  lv_nuttx_init(&info, &result);

  if (result.disp == NULL)
    {
      syslog(LOG_ERR, "%s: display init failed\n", AV_TAG);
      lv_deinit();
      return -ENODEV;
    }

  syslog(LOG_INFO, "%s: display %ldx%ld\n", AV_TAG,
         (long)lv_display_get_horizontal_resolution(result.disp),
         (long)lv_display_get_vertical_resolution(result.disp));

  /* CJK font stack: FreeType TTF -> compiled-in SimSun -> Montserrat. */

  av_font_init();

  /* Wi-Fi status is polled from the tick; the interface itself is brought up
   * by /etc/wifi/start_wifi.sh during board boot. */

  ret = av_wifi_init();
  if (ret < 0)
    {
      syslog(LOG_WARNING, "%s: wifi init -> %d\n", AV_TAG, ret);
    }

  /* Voice loop.  Non fatal when the agent is absent. */

  av_voice_init();
  av_voice_set_stt_cb(av_on_stt, NULL);
  av_voice_set_reply_cb(av_on_reply, NULL);
  av_voice_set_speak_cb(av_on_spoken, NULL);

  /* Build the screen and connect the gestures. */

  memset(&events, 0, sizeof(events));
  events.on_ptt_down  = av_on_ptt_down;
  events.on_ptt_up    = av_on_ptt_up;
  events.on_idle_tap  = av_on_idle_tap;
  av_ui_set_events(&events);

  ret = av_ui_create();
  if (ret < 0)
    {
      syslog(LOG_ERR, "%s: ui init failed: %d\n", AV_TAG, ret);
      av_voice_deinit();
      av_wifi_deinit();
      lv_nuttx_deinit(&result);
      lv_deinit();
      return ret;
    }

  /* One timer drives everything: animations, worker result drain, Wi-Fi. */

  lv_timer_create(av_timer_cb, AV_TICK_MS, NULL);

#ifndef CONFIG_LV_USE_NUTTX_LIBUV
  if (result.indev != NULL)
    {
      lv_timer_t *itimer;

      lv_indev_set_mode(result.indev, LV_INDEV_MODE_TIMER);

      itimer = lv_indev_get_read_timer(result.indev);
      if (itimer != NULL)
        {
          lv_timer_set_period(itimer, AV_TICK_MS);
        }
    }
#endif

  syslog(LOG_INFO, "%s: entering event loop\n", AV_TAG);

#ifdef CONFIG_LV_USE_NUTTX_LIBUV
  av_uv_loop(&ui_loop, &result);
#else
  av_poll_loop();
#endif

  syslog(LOG_INFO, "%s: exiting\n", AV_TAG);

  av_ui_destroy();
  av_voice_deinit();
  av_wifi_deinit();
  av_font_deinit();
  lv_nuttx_deinit(&result);
  lv_deinit();

  return 0;
}

############################################################################
# Contest 2026 team 236 - "Anime Voice Companion"
#
# defconfig overlay for the Gemini-S1 board (r528s3-gemini-s1, Allwinner R528).
#
# This fragment is APPENDED to the vendor supplied base defconfig:
#
#   packages/ai_agent/defconfigs/gemini-s1/gemini-s1_defconfig
#        |
#        |   deploy/gemini-s1/deploy-gemini-s1.sh
#        v
#   vendor/allwinnertech/boards/r528/r528s3-gemini-s1/configs/nsh_minidisplay/defconfig
#
# Keeping the vendor base as the source of truth (instead of committing a full
# 600 line copy) means we automatically pick up vendor fixes.  Later
# assignments win in a NuttX .config, so every override below is effective.
#
# Apply with:  bash deploy/gemini-s1/deploy-gemini-s1.sh
############################################################################


# --------------------------------------------------------------------------
# 1. This app owns the panel
#
# The vendor base enables the mini launcher, which is itself an LVGL
# application holding /dev/lcd0.  Two LVGL apps cannot share the framebuffer,
# so the launcher (and its mini_memo page) is switched off and the anime voice
# companion becomes the only on-screen application.
# --------------------------------------------------------------------------

# CONFIG_LUNCHER_MINI_APP is not set
# CONFIG_LVX_USE_DEMO_MINI_MEMO is not set


# --------------------------------------------------------------------------
# 2. The application itself
# --------------------------------------------------------------------------

CONFIG_LVX_USE_DEMO_ANIME_VOICE=y

CONFIG_ANIME_VOICE_PROGNAME="anime_voice"
CONFIG_ANIME_VOICE_PRIORITY=100

# Task stack.  The launcher used 40960; we run FreeType glyph rasterisation in
# the same thread, so keep plenty of headroom.
CONFIG_ANIME_VOICE_STACKSIZE=65536

# Worker stacks for ASR / LLM / TTS.  CONFIG_PTHREAD_STACK_DEFAULT on this
# board is only 4096, which is far too small for mbedTLS + HTTP.  av_voice.c
# always requests this size explicitly.
CONFIG_ANIME_VOICE_THREAD_STACK=65536

# Font: the vendor base ships MiSans inside the `res` partition; when it is
# absent av_font.c falls back to the compiled-in SimSun CJK face below.
CONFIG_ANIME_VOICE_FONT_PATH="/resource/fonts/MiSans-Normal.ttf"

# Wi-Fi: must match CONFIG_WIRELESS_WAPI_CONFIG_PATH so that the board's own
# bring-up script finds the credentials our on-screen setup page writes.
CONFIG_ANIME_VOICE_WIFI_CFG="/data/etc/wifi/wapi.conf"
CONFIG_ANIME_VOICE_WIFI_SCRIPT="/etc/wifi/start_wifi.sh"

CONFIG_ANIME_VOICE_PTT_MS=5000


# --------------------------------------------------------------------------
# 3. Fonts
#
# Guarantee CJK glyphs even when /resource/fonts/MiSans-Normal.ttf is not
# present in the res partition: the bitmap face is compiled straight into the
# firmware, so the Chinese UI can never degrade to empty boxes on stage.
# --------------------------------------------------------------------------

CONFIG_LV_FONT_SIMSUN_16_CJK=y

# av_font()'s last-resort fallback references these three.
CONFIG_LV_FONT_MONTSERRAT_12=y
CONFIG_LV_FONT_MONTSERRAT_16=y
CONFIG_LV_FONT_MONTSERRAT_20=y


# --------------------------------------------------------------------------
# 4. LVGL widget set used by av_ui.c / av_char.c
#
# All of these default to "y if !LV_CONF_MINIMAL", so pinning them costs
# nothing and protects against a future LV_CONF_MINIMAL=y in the vendor base.
# --------------------------------------------------------------------------

CONFIG_LV_USE_FLEX=y
CONFIG_LV_USE_LABEL=y
CONFIG_LV_USE_BUTTON=y
CONFIG_LV_USE_BAR=y
CONFIG_LV_USE_LIST=y
CONFIG_LV_USE_KEYBOARD=y
CONFIG_LV_USE_TEXTAREA=y


# --------------------------------------------------------------------------
# 5. Keep QuickApp out of the link
#
# The contest branch does NOT ship the QuickApp prebuilt archive
# (vendor/openvela/boards/vela/libs/armv7a_cmake/ is empty), so anything that
# drags in QApplication* / QApp* / InspectHost* / jse_system_* symbols fails at
# link time.  The vendor ai_agent defconfig already leaves these off; the
# explicit lines below document the invariant and protect against drift.
#
# Note: CONFIG_MEDIA is NOT part of this group.  The media framework builds
# from source and is required by the AI agent's capture / playback path - see
# packages/ai_agent/defconfigs/gemini-s1/README.md.
# --------------------------------------------------------------------------

# CONFIG_QUICKAPP is not set
# CONFIG_QUICKAPP_VAPP is not set
# CONFIG_QUICKAPP_AIOTJSC is not set
# CONFIG_FEATURE_FRAMEWORK is not set
# CONFIG_UIKIT is not set
# CONFIG_LIB_YOGA is not set
# CONFIG_INTERPRETERS_QUICKJS is not set


# --------------------------------------------------------------------------
# 7. Display bring-up path (fix: black screen after first ai_agent build)
#
# r528_late_initialize() picks the LCD init branch like this:
#
#   #if  defined(CONFIG_LCD_FRAMEBUFFER)   -> r528_disp_init() only
#   #elif defined(CONFIG_LCD)              -> board_lcd_initialize()
#                                            + lcddev_register(0) -> /dev/lcd0
#
# The vendor ai_agent base enables LCD_FRAMEBUFFER, which makes the board
# register only the sunxi /dev/fb0 - and LVGL's NuttX LCD backend (this app,
# and the launcher before it) opens /dev/lcd0.  Without lcddev_register()
# /dev/lcd0 never appears, lv_nuttx_init() fails, and the panel stays black.
# Turn LCD_FRAMEBUFFER off so the board goes back to the LCD branch, exactly
# the path the pre-ai_agent "known good" images used.
# --------------------------------------------------------------------------

# CONFIG_LCD_FRAMEBUFFER is not set
# CONFIG_LCD_EXTERNINIT is not set


# --------------------------------------------------------------------------
# 6. cJSON (ai_agent dependency)
#
# The AI agent's infra/config_store.c, core/session_mgr.c and
# core/context_builder.c call cJSON_* directly.  The vendor base defconfig does
# not enable it (only packages/demos/mini_memo/Kconfig selects it), so without
# the line below the final link fails with undefined cJSON_* symbols.
# --------------------------------------------------------------------------

CONFIG_NETUTILS_CJSON=y

/* ========================================================================
 * Contest 2026 team 236 - "Anime Voice Companion" autostart block
 *
 * This is NOT a standalone file.  deploy/gemini-s1/deploy-gemini-s1.sh splices
 * it into the board's NSH bring-up script:
 *
 *   vendor/allwinnertech/boards/r528/r528s3-gemini-s1/src/etc/init.d/rcS.nsh
 *
 * immediately before the final `echo "Boot nsh ok"` line.  rcS.nsh goes
 * through the C preprocessor (note the #ifdef below) and is then executed by
 * NSH, so both preprocessor and shell syntax apply.
 *
 * Boot order rationale
 * --------------------
 *   mediad        started earlier by rcS.nsh, needed by the ASR/TTS capture
 *                 and playback path.
 *   ai_agent      provides the voice channel (Volcengine ASR/TTS) and the
 *                 VelaClaw LLM client.  Started only when an LLM backend has
 *                 already been provisioned, because it takes over the console
 *                 with its own `vela>` prompt - keeping the first boot's NSH
 *                 free is what makes the one-time `set_llm` / `set_volc_asr`
 *                 step possible.
 *   anime_voice   the on-screen companion.  Always started; without a
 *                 reachable agent it degrades to offline small talk instead of
 *                 failing.
 * ======================================================================== */

#ifdef CONFIG_LVX_USE_DEMO_ANIME_VOICE

if [ -f /data/ai_agent/config/config.json ]
then
  echo "Starting ai_agent (LLM backend already provisioned)..."
  ai_agent &
  sleep 2
fi

echo "Starting anime_voice..."
anime_voice &

#endif /* CONFIG_LVX_USE_DEMO_ANIME_VOICE */


"}
